// Code equivalent to a 3D / Solid Mechanics / Stationary wizard run
Model model = ModelUtil.create("Model");
model.component().create("comp1", true);
model.component("comp1").geom().create("geom1", 3);
model.component("comp1").mesh().create("mesh1");
model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
model.study().create("std1");
model.study("std1").create("stat", "Stationary");

model.component().create("comp1", true);
model.component("comp1").geom().create("geom1", 3);
model.component("comp1").mesh().create("mesh1");
model.component("comp1").sorder("quadratic");

// a mesh component (mesh part) under Global Definitions
model.component().create("mcomp1", "MeshComponent");
model.component("mcomp1").geom().create("mgeom1", 3);
model.component("mcomp1").mesh().create("mpart1", "mgeom1");

model.param().set("L", "10[cm]", "Bar length");
model.param().set("w", "L/5", "Bar width");
model.param().set("T0", "293.15[K]", "Ambient temperature");

// read back
String expr = model.param().get("w");            // "L/5"
double val  = model.param().evaluate("L");        // 0.1 (SI base unit)
String unit = model.param().evaluateUnit("L");    // "m"
model.param().remove("T0");

model.param().set("L", "10[cm]");
model.param().set("k", "400[W/(m*K)]");

// an alternative set of values
model.param().paramCase().create("pc1");
model.param().paramCase("pc1").set("L", "20[cm]");
model.param().paramCase("pc1").set("k", "160[W/(m*K)]");

// take the value of L from that case
model.param().setFromCase("L", "pc1");

// global variables
model.variable().create("var1");
model.variable("var1").set("Q_tot", "P_in/V_dom", "Volumetric heat source");

// component variables restricted to domains 1 and 2
model.component("comp1").variable().create("e1");
model.component("comp1").variable("e1").set("e", "x+1");
model.component("comp1").variable("e1").selection().geom("geom1", 3);
model.component("comp1").variable("e1").selection().set(new int[]{1, 2});

// a second collection with a different definition, using a named selection
model.component("comp1").variable().create("e2");
model.component("comp1").variable("e2").set("e", "x-1");
model.component("comp1").variable("e2").selection().named("sel1");

model.func().create("an1", "Analytic");
model.func("an1").set("funcname", "k_T");
model.func("an1").set("expr", "400 - 0.07*(T-293.15)");
model.func("an1").set("args", new String[]{"T"});
model.func("an1").set("argunit", "K");
model.func("an1").set("fununit", "W/(m*K)");
model.func("an1").setIndex("plotargs", "200", 0, 1);
model.func("an1").setIndex("plotargs", "800", 0, 2);
// used elsewhere as k_T(T)

model.func().create("int1", "Interpolation");
model.func("int1").set("source", "table");
model.func("int1").set("funcname", "cp_T");
model.func("int1").set("table", new String[][]{
    {"200", "890"}, {"300", "904"}, {"400", "949"}, {"500", "996"}});
model.func("int1").set("interp", "piecewisecubic");
model.func("int1").set("extrap", "const");
model.func("int1").set("argunit", "K");
model.func("int1").set("fununit", "J/(kg*K)");

// from a file instead
model.func().create("int2", "Interpolation");
model.func("int2").set("source", "file");
model.func("int2").set("filename", "C:/data/bh_curve.txt");
model.func("int2").set("struct", "spreadsheet");
model.func("int2").setIndex("funcnametable", "B_H", 0, 0);
model.func("int2").importData();

model.func().create("pw1", "Piecewise");
model.func("pw1").set("funcname", "k_T");
model.func("pw1").set("arg", "T");
model.func("pw1").set("pieces", new String[][]{
    {"200", "400", "0.6"},
    {"400", "800", "0.6+0.001*(T-400)"}});
model.func("pw1").set("smooth", "contd1");
model.func("pw1").set("smoothzone", 0.05);
model.func("pw1").set("extrap", "const");
model.func("pw1").set("argunit", "K");
model.func("pw1").set("fununit", "W/(m*K)");

model.func().create("step1", "Step");
model.func("step1").set("funcname", "sw");
model.func("step1").set("location", "0.5");
model.func("step1").set("from", 0);
model.func("step1").set("to", 1);
model.func("step1").set("smooth", true);
model.func("step1").set("smoothzone", "0.05");
model.func("step1").set("ncontder", 2);
// used e.g. as P0*sw(t[1/s]) in a time-dependent source

model.component("comp1").material().create("mat1", "Common");
model.component("comp1").material("mat1").label("Copper");
model.component("comp1").material("mat1").selection().set(new int[]{1, 2});
model.component("comp1").material("mat1").propertyGroup("def")
     .set("density", "8960[kg/m^3]");
model.component("comp1").material("mat1").propertyGroup("def")
     .set("thermalconductivity", new String[]{"400[W/(m*K)]", "0", "0", "0", "400[W/(m*K)]", "0", "0", "0", "400[W/(m*K)]"});
model.component("comp1").material("mat1").propertyGroup("def")
     .set("heatcapacity", "385[J/(kg*K)]");

// link a component material to a global material
model.component("comp1").material().create("matlnk1", "Link");
model.component("comp1").material("matlnk1").set("link", "mat1");

model.component("comp1").selection().create("sel1");        // Explicit by default
model.component("comp1").selection("sel1").geom("geom1", 2);  // boundary level in 3D
model.component("comp1").selection("sel1").set(new int[]{3, 4, 7});
model.component("comp1").selection("sel1").label("Heated walls");

// all exterior boundaries of a 2D geometry
model.component("comp1").selection().create("outer")
     .geom("geom1", 2, 1, new String[]{"exterior"});
model.component("comp1").selection("outer").all();

// consume it from a physics feature
model.component("comp1").physics("ht").feature("temp1").selection().named("sel1");

model.component("comp1").selection().create("box1", "Box");
model.component("comp1").selection("box1").label("Inlet region");
model.component("comp1").selection("box1").set("entitydim", "2");
model.component("comp1").selection("box1").set("xmin", "-0.01");
model.component("comp1").selection("box1").set("xmax", "0.01");
model.component("comp1").selection("box1").set("condition", "inside");

// same idea with a ball
model.component("comp1").selection().create("ball1", "Ball");
model.component("comp1").selection("ball1").set("entitydim", "2");
model.component("comp1").selection("ball1").set("posx", "1");
model.component("comp1").selection("ball1").set("posy", "1");
model.component("comp1").selection("ball1").set("posz", "1");
model.component("comp1").selection("ball1").set("r", "0.5");

model.component("comp1").selection().create("sel1");
model.component("comp1").selection("sel1").geom("geom1", 3);
model.component("comp1").selection("sel1").set(new int[]{1, 2});

model.component("comp1").selection().create("adj1", "Adjacent");
model.component("comp1").selection("adj1").label("Skin of the solid");
model.component("comp1").selection("adj1").set("input", new String[]{"sel1"});
model.component("comp1").selection("adj1").set("exterior", "on");
model.component("comp1").selection("adj1").set("interior", "off");

// boolean selections
model.component("comp1").selection().create("dif1", "Difference");
model.component("comp1").selection("dif1").set("add", new String[]{"box1"});
model.component("comp1").selection("dif1").set("subtract", new String[]{"sel1"});

model.component("comp1").cpl().create("intop1", "Integration");
model.component("comp1").cpl("intop1").set("opname", "intBnd");
model.component("comp1").cpl("intop1").selection().geom("geom1", 2);
model.component("comp1").cpl("intop1").selection().set(new int[]{3, 4});
model.component("comp1").cpl("intop1").set("intorder", "4");
model.component("comp1").cpl("intop1").set("frame", "spatial");

model.variable().create("var1");
model.variable("var1").set("Q_tot", "comp1.intBnd(ht.ntflux)", "Total heat flux");

model.component("comp1").cpl().create("genext1", "GeneralExtrusion");
model.component("comp1").cpl("genext1").set("opname", "mapTop");
model.component("comp1").cpl("genext1").selection().geom("geom1", 2);
model.component("comp1").cpl("genext1").selection().set(new int[]{5});
// evaluate the source boundary value directly above each destination point
model.component("comp1").cpl("genext1").setIndex("dstmap", "x", 0);
model.component("comp1").cpl("genext1").setIndex("dstmap", "y", 1);
model.component("comp1").cpl("genext1").set("usesrcmap", "off");
model.component("comp1").cpl("genext1").set("usenan", "on");
// used as comp1.mapTop(T) anywhere in the model

model.component("comp1").coordSystem().create("sys2", "geom1", "Rotated");
model.component("comp1").coordSystem("sys2").label("Fiber direction");
model.component("comp1").coordSystem("sys2").set("rotationSequence", "ZXZ");
model.component("comp1").coordSystem("sys2").setIndex("angle", "30[deg]", 0);
model.component("comp1").coordSystem("sys2").setIndex("angle", "0", 1);
model.component("comp1").coordSystem("sys2").setIndex("angle", "0", 2);

// base-vector system, the other common choice
model.component("comp1").coordSystem().create("sys3", "VectorBase");
model.component("comp1").coordSystem("sys3").set("base",
    new String[][]{{"0","1","0"},{"0","0","1"},{"1","0","0"}});

model.component("comp1").probe().create("pdom1", "DomainPoint");
model.component("comp1").probe("pdom1").model("comp1");
model.component("comp1").probe("pdom1").set("method", "none");
model.component("comp1").probe("pdom1").setIndex("coords", 0.05, 0);
model.component("comp1").probe("pdom1").setIndex("coords", 0.02, 1);
model.component("comp1").probe("pdom1").setIndex("coords", 0.01, 2);
model.component("comp1").probe("pdom1").feature("ppb1").set("expr", "T");
model.component("comp1").probe("pdom1").feature("ppb1").set("unit", "K");

// probes must be prepared explicitly when solving from the API
model.component("comp1").probe("pdom1").genResult(null);

model.param().set("L", "10[cm]");
model.param().set("rho", "8960[kg/m^3]");
model.param().set("dT", "0.5[ft]+33[mm]");   // mixed units are converted automatically

model.component("comp1").geom("geom1").lengthUnit("mm");
model.component("comp1").geom("geom1").angularUnit("deg");

// user-defined unit system
UnitSystem us = model.unitSystem().create("cgs2");
model.baseSystem("cgs2");
us.baseUnit().create("centimeter", "cm", "length");

model.methodCall().create("mcall1", "buildGeometry");
model.methodCall("mcall1").set("paramname", "p1");
model.methodCall("mcall1").set("paramvalues", new double[]{2.3, 3.7, 5.6});
model.methodCall("mcall1").set("sendmail", true);
model.methodCall("mcall1").run();

String[] names = model.methodCall("mcall1").inputNames();
String[] all   = model.methodCall("mcall1").methods();

Steps in the COMSOL Desktop:
1. Build the geometry (Geometry > Build All) - compacting works best on a built geometry.
2. File > Compact History.
3. File > Save As, choose "Model file for Java (*.java)", save as model.java.
4. Run the exported file headless:
   comsol batch -inputfile model.java

The exported file has the shape:
   public static Model run() {
     Model model = ModelUtil.create("Model");
     model.modelPath("C:/work");
     model.param().set("L", "10[cm]");
     model.component().create("comp1", true);
     ...
     return model;
   }
